import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 8000,
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true
      }
    }
  }
})

import { useState, useEffect } from 'react'
import './App.css'

function App() {
  const [readings, setReadings] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    fetch('/api/readings')
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return res.json()
      })
      .then(data => {
        setReadings(data)
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [])

  // Compute summary stats
  const count = readings.length
  const temps = readings.map(r => r.temperature_c)
  const minTemp = temps.length ? Math.min(...temps) : null
  const maxTemp = temps.length ? Math.max(...temps) : null
  const avgTemp = temps.length ? (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1) : null

  return (
    <div className="dashboard">
      <h1>🌡️ Sensor Dashboard</h1>

      {/* Summary Card */}
      <div className="summary-card">
        <h2>Summary</h2>
        <div className="summary-grid">
          <div className="stat">
            <span className="stat-label">Total Readings</span>
            <span className="stat-value">{count}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Min Temp</span>
            <span className="stat-value">{minTemp !== null ? minTemp.toFixed(1) + '°C' : '—'}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Max Temp</span>
            <span className="stat-value">{maxTemp !== null ? maxTemp.toFixed(1) + '°C' : '—'}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Avg Temp</span>
            <span className="stat-value">{avgTemp !== null ? avgTemp + '°C' : '—'}</span>
          </div>
        </div>
      </div>

      {/* Data Table */}
      <div className="table-container">
        <h2>Readings</h2>
        {loading && <p className="loading">Loading readings...</p>}
        {error && <p className="error">Error: {error}</p>}
        {!loading && !error && (
          <table className="readings-table">
            <thead>
              <tr>
                <th>Timestamp</th>
                <th>Sensor</th>
                <th>Temperature (°C)</th>
              </tr>
            </thead>
            <tbody>
              {readings.map((r, i) => (
                <tr key={i}>
                  <td>{r.timestamp}</td>
                  <td>{r.sensor}</td>
                  <td>{r.temperature_c.toFixed(1)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  )
}

export default App

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0f172a;
  color: #e2e8f0;
  min-height: 100vh;
}

#root {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 1.5rem;
  color: #38bdf8;
}

/* Summary cards */
.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
  margin-bottom: 2rem;
}

.card {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  padding: 1.25rem;
  text-align: center;
}

.card .label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
  margin-bottom: 0.5rem;
}

.card .value {
  font-size: 1.75rem;
  font-weight: 700;
  color: #38bdf8;
}

.card .value.min { color: #4ade80; }
.card .value.max { color: #f87171; }
.card .value.avg { color: #facc15; }

/* Table */
.table-wrap {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  overflow: hidden;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead {
  background: #334155;
}

th {
  padding: 0.75rem 1rem;
  text-align: left;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
}

td {
  padding: 0.6rem 1rem;
  border-top: 1px solid #334155;
  font-size: 0.9rem;
}

tbody tr:hover {
  background: #263044;
}

/* Loading / error states */
.loading,
.error {
  text-align: center;
  padding: 3rem;
  font-size: 1.1rem;
  color: #94a3b8;
}

.error {
  color: #f87171;
}
